    let mut score = post_residual as f64;

    // Penalize creating bins with very little space left
    if bin_residual < 10 {
        score += (10 - bin_residual) as f64 * 5.0;
    }

    // Reward bins that can fit the next item to minimize bin usage
    if fitting_bins_count > 0 && next_item_size > 0 {
        let future_score = post_residual as f64 + next_item_size as f64;
        if future_score <= bin_capacity {
            score -= (bin_capacity - future_score) as f64 * 2.0;
        }
    }

    // Penalize opening new bins
    score += open_bins_count as f64 * 1.5;

    // Reward bins with lower mean residual to balance load
    if mean_residual > bin_residual {
        let residual_diff = mean_residual - bin_residual;
        score -= residual_diff * 0.3;
    }

    score
}

