pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize small gaps that are too small to fit the next item
    if post_residual > 0 && post_residual < next_item_size {
        score -= (post_residual as f64 / next_item_size as f64).powf(2.0);
    }

    // Penalize bins with very low remaining capacity
    if bin_residual < 30 {
        score -= ((bin_capacity - bin_residual) as f64 / 15.0).powf(2.0);
    }

    // Penalize open bins count to encourage closing bins early
    score -= (open_bins_count as f64 * 0.5).powf(1.5);

    // Reward bins with higher mean residual
    score += mean_residual.powf(1.5);

    score
}

