    let next_item_fit_factor = if next_item_size <= bin_residual { 1.6 } else { 0.4 };
    let fitting_bins_bonus = if fitting_bins_count > 2 { (fitting_bins_count - 2) as f64 * 0.9 } else { 0.0 };

    // Lookahead trade-off
    let lookahead_tradeoff_factor = if post_residual < mean_residual * 1.5 { 7.2 } else if post_residual < mean_residual * 3.0 { 4.1 } else { 1.6 };

    let score = -(post_residual * (3.0 + 8.0 * stream_progress) * residual_factor * lookahead_tradeoff_factor * bin_utilization_factor * open_bins_penalty * next_item_fit_factor + fitting_bins_bonus);
    score
}

